 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform zero/divider rows and columns partition the canvas into panels.
    row_dividers = [r for r in range(h) if len(set(grid[r])) == 1]
    col_dividers = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    divider = grid[row_dividers[0]][0]
    row_cuts = [-1] + [r for r in row_dividers if grid[r][0] == divider] + [h]
    col_cuts = [-1] + [c for c in col_dividers if grid[0][c] == divider] + [w]

    out = []
    for ra, rb in zip(row_cuts, row_cuts[1:]):
        if rb == ra + 1:
            continue
        row = []
        for ca, cb in zip(col_cuts, col_cuts[1:]):
            if cb == ca + 1:
                continue
            panel = [
                (r - ra - 1, c - ca - 1)
                for r in range(ra + 1, rb)
                for c in range(ca + 1, cb)
                if grid[r][c] not in (divider, 0, 7, 9)
            ]
            # Find the panel containing the distinctive pair: two marks,
            # aligned vertically with exactly one cell between them.
            selected = False
            if len(panel) == 2:
                (r1, c1), (r2, c2) = panel
                selected = c1 == c2 and abs(r1 - r2) == 2
            row.append(1 if selected else 0)
        out.append(row)
    return out


if __name__ == '__main__':
    demo = [[0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,3,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,3,0], [3,0,0,0,9,0,0,0,0,9,0,0,3,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [9]*19, [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,3], [0,3,0,0,9,3,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,3,0,9,0,0,0,0], [0,3,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [9]*19, [0,0,0,3,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,3,9,0,0,0,0,9,0,0,3,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,3,0,0,0,9,0,0,0,0], [9]*19, [0,0,0,0,9,0,0,0,0,9,0,3,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0], [0,0,0,0,9,0,3,0,0,9,0,0,0,0,9,0,0,0,3], [0,3,0,0,9,0,0,0,0,9,0,0,0,0,9,0,0,0,0]]
